"""Subquery decorrelation: correlated scalar subqueries (COUNT, SUM, MAX and bare), EXISTS, NOT EXISTS, IN and NOT IN
with NULLs, ANY and ALL over empty and NULL sets, LATERAL and UNNEST correlation, two levels of correlation, bodies
with LIMIT, DISTINCT, GROUP BY, HAVING and windows, non-equality and OR correlation, shadowed outer names, duplicate
keys, and subqueries in the SELECT list, ON and HAVING."""

import random

from ._base import expand

CMP = "{=|<|>|<=|>=|<>}"
AGGS = "{COUNT(*)|COUNT(u.w)|SUM(u.w)|MAX(u.w)|MIN(u.w)|AVG(u.w)|COUNT(DISTINCT u.w)|ANY_VALUE(u.w)}"
CORR = "{u.k = t.y|u.k = t.x|u.w = t.x|u.k = t.y AND u.w > t.x|u.k = t.y OR u.w = t.x|u.k < t.y|u.k = t.y AND u.v = t.s|u.k IS NOT DISTINCT FROM t.y|u.k = t.y + 1}"
EXTRA = "{|AND u.w > 0|AND u.w IS NOT NULL|AND u.v = 'a'}"

