_NULLABLE = {"t": ["x", "y"], "u": ["w", "v"], "p": ["tid", "n", "b"]}


def cases(seed: int, count: int) -> list[dict]:
    """Template cases, a third of them with extra NOT NULL columns (the rules that read declared nullability)."""

    rng = random.Random(seed * 31 + 7)
    out = expand(TEMPLATES, seed, count, "decorrelation")
    for case in out:
        if rng.random() < 0.35:
            constraints = case["constraints"]
            for table, columns in _NULLABLE.items():
                for column in columns:
                    if rng.random() < 0.5:
                        rules = constraints.setdefault(table, {"not_null": [], "keys": []})
                        if column not in rules.setdefault("not_null", []):
                            rules["not_null"].append(column)
            if rng.random() < 0.5:
                constraints.setdefault("u", {"not_null": [], "keys": []})
                constraints["u"].setdefault("keys", [["k"]])
                constraints["u"].setdefault("not_null", [])
                if "k" not in constraints["u"]["not_null"]:
                    constraints["u"]["not_null"].append("k")
    return out
